cat > /tmp/validate-dialog.mjs << 'EOF'
import { chromium } from '/workspace/node_modules/playwright/index.mjs';
import fs from 'node:fs';

const browser = await chromium.launch({ headless: true });
const ctx = await browser.newContext({ acceptDownloads: true, viewport: { width: 1440, height: 1200 } });
const page = await ctx.newPage();
page.on('pageerror', (e) => console.log('PAGE_ERROR:', String(e)));
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE_ERR:', m.text().slice(0,200)); });

await page.goto('http://localhost:5173/', { waitUntil: 'networkidle', timeout: 60000 });
await page.waitForTimeout(1500);

function openDialogs() {
  return page.evaluate(() => {
    const out = [];
    document.querySelectorAll('[role="dialog"], [aria-modal="true"], .kern-modal, [class*="modal" i]').forEach(d => {
      const r = d.getBoundingClientRect();
      out.push({ role: d.getAttribute('role'), cls: d.className.toString().slice(0,80), visible: r.width > 0 && r.height > 0, text: d.innerText.slice(0,150).replace(/\n/g,' | ') });
    });
    return out;
  });
}

console.log('DIALOGS_INITIAL:', JSON.stringify(await openDialogs()));

// 1. click "Einfache Feldgruppe"
await page.getByRole('button', { name: 'Einfache Feldgruppe' }).first().click();
await page.waitForTimeout(1200);
console.log('DIALOGS_AFTER_FG:', JSON.stringify(await openDialogs()));

// If a dialog with Übernehmen is visible, confirm it
const uebernehmen = page.getByRole('button', { name: 'Übernehmen' });
if (await uebernehmen.first().isVisible().catch(() => false)) {
  await uebernehmen.first().click();
  await page.waitForTimeout(1200);
  console.log('CONFIRMED_FIELDGROUP_DIALOG');
}
await page.screenshot({ path: '/tmp/step1-fieldgroup.png', fullPage: true });

// 2. click "Einzeiliges Textfeld"
await page.getByRole('button', { name: 'Einzeiliges Textfeld' }).first().click();
await page.waitForTimeout(1200);
console.log('DIALOGS_AFTER_MODULE:', JSON.stringify(await openDialogs()));
const ub2 = page.getByRole('button', { name: 'Übernehmen' });
if (await ub2.first().isVisible().catch(() => false)) {
  await ub2.first().click();
  await page.waitForTimeout(1200);
  console.log('CONFIRMED_MODULE_DIALOG');
}
await page.screenshot({ path: '/tmp/step2-module.png', fullPage: true });

// 3. download model
const [download] = await Promise.all([
  page.waitForEvent('download', { timeout: 10000 }).catch(() => null),
  page.getByRole('button', { name: 'JSON herunterladen' }).first().click(),
]);
if (download) {
  const p = '/tmp/model-final.json';
  await download.saveAs(p);
  console.log('FINAL_MODEL:', fs.readFileSync(p, 'utf8').slice(0, 1500));
} else console.log('NO_DOWNLOAD');
await browser.close();
EOF
node /tmp/validate-dialog.mjs; echo "EXIT: $?"

